pub fn to_sexpr (node : ParseTree < '_ >) -> String { let mut s = String :: new () ; node_to_sexpr (node , 0 , & mut s) . expect ("error") ; s }
fn node_to_sexpr (node : ParseTree < '_ > , indent : usize , w : & mut impl Write) -> fmt :: Result { let children = node . children () ; if children . is_empty () { writeln ! (w , "{:indent$}{}" , "" , node . display_name ()) } else { writeln ! (w , "{:indent$}({}" , "" , node . display_name ()) ? ; for child in children { node_to_sexpr (child , indent + 2 , w) ? ; } writeln ! (w , "{:indent$})" , "") } } 
/// Converts a parse tree to JSON format for visualization.
 
/// Returns a JSON string with nodes and edges arrays.
 pub fn to_json (node : ParseTree < '_ >) -> String { let mut nodes = Vec :: new () ; let mut edges = Vec :: new () ; let mut next_id = 0u32 ; build_json_graph (node , & mut nodes , & mut edges , & mut next_id) ; let result = serde_json :: json ! ({ "nodes" : nodes , "edges" : edges }) ; result . to_string () }
fn build_json_graph (node : ParseTree < '_ > , nodes : & mut Vec < serde_json :: Value > , edges : & mut Vec < serde_json :: Value > , next_id : & mut u32 ,) -> u32 { let my_id = * next_id ; * next_id += 1 ; let span = node . span () ; let kind = match node { ParseTree :: Token (_) => "Token" , _ => "Nonterminal" , } ; nodes . push (serde_json :: json ! ({ "id" : my_id , "kind" : kind , "label" : node . display_name () , "start" : span . left_extent , "end" : span . right_extent })) ; for child in node . children () { let child_id = build_json_graph (child , nodes , edges , next_id) ; edges . push (serde_json :: json ! ({ "src" : my_id , "dest" : child_id })) ; } my_id }
